using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "InvokeCustomBattleActionDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Any/InvokeCustomBattleActionDescription", order = 0)]
public class InvokeCustomBattleActionDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		InvokeAction invokeAction = battleAction as InvokeAction;
		string text = "";
		if (invokeAction.EnableExtraAction)
		{
			text = invokeAction.ExtraBattleAction.GetActionDescription(invokeAction.ExtraActionValue) + "\n";
		}
		return text + Smart.Format(GetRawLocalizedDescription(battleAction), invokeAction.StartingEpicPercentage);
	}
}
